var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);System.IO.File.Copy(scene.path,"Assets/Temp/MountainPassPolish~/Test_Before.unity",false);var map=GameObject.Find("MountainPassEnvironment");int added=0;foreach(var filter in map.GetComponentsInChildren<MeshFilter>(true)){string n=filter.name;if(!n.StartsWith("Pine_")&&!n.StartsWith("Pine_Arena")&&!n.StartsWith("Pine_Shrine")&&n!="Gate_Threshold_1"&&!n.Contains("Wall_"))continue;var collider=filter.GetComponent<MeshCollider>();if(collider==null){collider=filter.gameObject.AddComponent<MeshCollider>();collider.sharedMesh=filter.sharedMesh;collider.convex=false;added++;}}
var gate=UnityEngine.Object.FindFirstObjectByType<Cheon.Prototype.MountainPass.PassBossEntrance>().transform;var gateMesh=GameObject.Find("MountainPassEnvironment/Hanok_Gate_Placement").GetComponentsInChildren<MeshCollider>().First();var rows=new System.Collections.Generic.List<object>();for(float y=37.5f;y<48f;y+=.5f){var solid=new System.Collections.Generic.List<float>();for(float x=-6f;x<=6;x+=.1f){var point=gate.TransformPoint(new Vector3(x,y-gate.position.y,-4));RaycastHit hit;if(gateMesh.Raycast(new Ray(point,gate.forward),out hit,8))solid.Add((float)System.Math.Round(x,2));}rows.Add(new{y,solid});}System.IO.File.WriteAllText("Assets/Temp/MountainPassPolish~/Test_GateOpening.json",Newtonsoft.Json.JsonConvert.SerializeObject(rows));return new{added,gate=gateMesh.name};
